// Find the point with the lowest y-coordinate (and leftmost if tie)
auto p0 = std::min_element(points.begin(), points.end(),
    [](const Point2d& a, const Point2d& b) {
        return a.y() < b.y() || (a.y() == b.y() && a.x() < b.x());
    });

// Sort points by polar angle with p0
std::sort(points.begin(), points.end(), [p0](const Point2d& a, const Point2d& b) {
    double cross = (a.x() - p0->x()) * (b.y() - p0->y()) -
                   (a.y() - p0->y()) * (b.x() - p0->x());
    if (cross == 0) {
        double dist_a = (a.x() - p0->x()) * (a.x() - p0->x()) +
                        (a.y() - p0->y()) * (a.y() - p0->y());
        double dist_b = (b.x() - p0->x()) * (b.x() - p0->x()) +
                        (b.y() - p0->y()) * (b.y() - p0->y());
        return dist_a < dist_b;
    }
    return cross > 0;
});

// Remove duplicates
std::vector<Point2d> hull;
hull.push_back(*p0);
for (size_t i = 1; i < points.size(); ++i) {
    if (i > 0 && points[i] == points[i-1]) continue;
    hull.push_back(points[i]);
}

// Graham scan
for (size_t i = 2; i < hull.size(); ++i) {
    while (hull.size() > 1) {
        Point2d a = hull[hull.size() - 2];
        Point2d b = hull[hull.size() - 1];
        Point2d c = hull[i];

        double cross = (b.x() - a.x()) * (c.y() - a.y()) -
                       (b.y() - a.y()) * (c.x() - a.x());

        if (cross <= 0) {
            hull.pop_back();
        } else {
            break;
        }
    }
}

return hull;

